/** Run async work in order without `await` inside a `for` loop (eslint no-await-in-loop). */
async function runSequentially<T>(
  items: readonly T[],
  run: (item: T) => Promise<void>,
): Promise<void> {
  await items.reduce(
    (chain, item) => chain.then(() => run(item)),
    Promise.resolve(),
  );
}

